CREATE TABLE notifications (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,title VARCHAR(160) NOT NULL,message VARCHAR(1000) NOT NULL,type VARCHAR(30) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_notification_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_notifications_user(user_id),INDEX idx_notifications_created(created_at));
CREATE TABLE notices (id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(180) NOT NULL,content TEXT NOT NULL,priority VARCHAR(20) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_notice_creator FOREIGN KEY(created_by) REFERENCES users(id),INDEX idx_notices_active(active),INDEX idx_notices_created(created_at));
CREATE TABLE feedback (id BIGINT PRIMARY KEY AUTO_INCREMENT,event_id BIGINT NOT NULL,user_id BIGINT NOT NULL,rating INT NOT NULL,comment VARCHAR(2000),created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_feedback_event_user UNIQUE(event_id,user_id),CONSTRAINT fk_feedback_event FOREIGN KEY(event_id) REFERENCES events(id),CONSTRAINT fk_feedback_user FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_feedback_event(event_id));
CREATE TABLE certificates (id BIGINT PRIMARY KEY AUTO_INCREMENT,certificate_id VARCHAR(60) NOT NULL,registration_id BIGINT NOT NULL,issued_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_certificate_id UNIQUE(certificate_id),CONSTRAINT uk_certificate_registration UNIQUE(registration_id),CONSTRAINT fk_certificate_registration FOREIGN KEY(registration_id) REFERENCES registrations(id));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT,ip_address VARCHAR(64),timestamp TIMESTAMP(6) NOT NULL,details TEXT,INDEX idx_audit_timestamp(timestamp),INDEX idx_audit_user(user_id),INDEX idx_audit_action(action),INDEX idx_audit_entity(entity_type,entity_id),CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
